actions.script:
import groovy.json.JsonSlurper

def pld = ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", agiPayloadId).one()
if (!pld) {
    ec.message.addError("AgiPayload not found for ID: ${agiPayloadId}")
    return
}

Map outMap = pld.getMap()
if (pld.payloadJsonData) {
    try {
        outMap.payload = new JsonSlurper().parseText(pld.payloadJsonData)
    } catch (Exception ignore) {}
}
if (pld.executionResultJson) {
    try {
        outMap.executionResult = new JsonSlurper().parseText(pld.executionResultJson)
    } catch (Exception ignore) {}
}

def facets = ec.entity.find("org.moqui.ai.payload.AgiPayloadFacet").condition("agiPayloadId", agiPayloadId).list()
outMap.facets = facets.collectEntries { [(it.facetKey): it.facetValue] }

context.payloadDetails = outMap

import groovy.json.JsonOutput import java.security.MessageDigest
Map modeMap = [ 'plan': 'AamPlan', 'build': 'AamBuild', 'orchestrate': 'AamOrchestrate', 'test': 'AamTest', 'query': 'AamQuery', 'history': 'AamHistory', 'discuss': 'AamDiscuss' ] String modeEnumId = modeMap.get(mode.toLowerCase()) ?: 'AamPlan'
Map rawPayloadMap = payload ?: [:] if (userPromptText) rawPayloadMap.userPromptText = userPromptText String payloadJsonStr = JsonOutput.toJson(rawPayloadMap)
MessageDigest md = MessageDigest.getInstance("SHA-256") String sha256Hex = md.digest(payloadJsonStr.getBytes("UTF-8")).encodeHex().toString()
String artId = null if (artifactUri) { def artVal = ec.entity.find("org.moqui.ai.AgiArtifact").condition("artifactPath", artifactUri).one() if (!artVal) { artVal = ec.entity.makeValue("org.moqui.ai.AgiArtifact") artVal.artifactPath = artifactUri artVal.artifactStatusEnumId = "AasDraft" artVal.setSequencedIdPrimary() artVal.create() } artId = artVal.agiArtifactId }
def payloadVal = agiPayloadId ? ec.entity.find("org.moqui.ai.payload.AgiPayload").condition("agiPayloadId", agiPayloadId).one() : null if (!payloadVal) { payloadVal = ec.entity.makeValue("org.moqui.ai.payload.AgiPayload") payloadVal.setSequencedIdPrimary() payloadVal.createdDate = ec.user.nowTimestamp payloadVal.statusId = "PlsDraft" } else { payloadVal.revisionNumber = (payloadVal.revisionNumber ?: 1) + 1 }
payloadVal.modeEnumId = modeEnumId payloadVal.targetComponent = targetComponent payloadVal.artifactUri = artifactUri payloadVal.targetMariaId = targetMariaId payloadVal.agiArtifactId = artId payloadVal.title = title ?: (userPromptText ? (userPromptText.length() > 50 ? userPromptText.substring(0, 47) + "..." : userPromptText) : "Untitled Payload") payloadVal.userPromptText = userPromptText payloadVal.payloadJsonData = payloadJsonStr payloadVal.contentSha256 = sha256Hex payloadVal.lastUpdatedStamp = ec.user.nowTimestamp
if (["AamBuild", "AamTest", "AamDiscuss"].contains(modeEnumId) && artId) { String weType = modeEnumId == "AamDiscuss" ? "WetDiscussion" : "WetIntent" String safeMariaId = targetMariaId ?: (artifactUri ? org.moqui.ide.ScreenEditorServices.generateMariaId(artifactUri, "root") : null)
Map weResult = ec.service.sync().name("org.moqui.ide.BlueprintServices.create#WorkEffortNode").parameters([ workEffortName: payloadVal.title, agiArtifactId: artId, sourceReferenceId: artifactUri, workEffortTypeEnumId: weType, targetMariaId: safeMariaId ]).call()
payloadVal.workEffortId = weResult.workEffortId }
payloadVal.createOrUpdate() context.agiPayloadId = payloadVal.agiPayloadId context.workEffortId = payloadVal.workEffortId
if (facets instanceof Map) { facets.each { k, v -> if (k && v != null) { def facetVal = ec.entity.makeValue("org.moqui.ai.payload.AgiPayloadFacet") facetVal.setSequencedIdPrimary() facetVal.agiPayloadId = payloadVal.agiPayloadId facetVal.facetKey = k.toString() facetVal.facetValue = v.toString() facetVal.create() } } }
Map execResult = [:] if (modeEnumId == "AamBuild") { payloadVal.statusId = "PlsStaged" execResult.status = "STAGED" execResult.message = "Build payload staged for AI assistant." } else if (modeEnumId == "AamTest") { payloadVal.statusId = "PlsStaged" execResult.status = "READY" execResult.message = "Test payload ready for test harness." } else { payloadVal.statusId = "PlsDraft" execResult.status = "RECORDED" execResult.message = "Payload context and intent saved." }
payloadVal.executionResultJson = JsonOutput.toJson(execResult) payloadVal.update()
context.statusId = payloadVal.statusId context.executionResult = execResult

import groovy.json.JsonSlurper
import org.moqui.resource.ResourceReference

StringBuilder prompt = new StringBuilder()
String normalizedMode = (mode ?: 'build').toLowerCase().trim()
if (['interview', 'elicitation', 'conversation'].contains(normalizedMode)) normalizedMode = 'discuss'
String safeUri = artifactUri ?: ""

// Cascade lookup across components: check agi-ide first, fallback to agi-ai
def loadFirstResource = { List<String> paths ->
    for (String path in paths) {
        try {
            ResourceReference rr = ec.resource.getLocationReference(path)
            if (rr != null && rr.getExists()) return rr.getText()
        } catch (Exception e) {
            ec.logger.warn("⚠️ [assemble#SystemInstruction] Error reading ${path}:${e.message}")
        }
    }
    return null
}

// 1. BASE FOUNDATIONS & GUARDRAILS
String foundation = loadFirstResource([
    "component://agi-ide/mcp/instructions/base/system-foundation.md",
    "component://agi-ai/mcp/instructions/base/system-foundation.md"
])
if (foundation) prompt.append(foundation.trim()).append("\n\n")

String guardrails = loadFirstResource([
    "component://agi-ide/mcp/instructions/base/guardrails.md",
    "component://agi-ai/mcp/instructions/base/guardrails.md"
])
if (guardrails) prompt.append(guardrails.trim()).append("\n\n")

// 2. ARTIFACT IDENTIFICATION
String matchedCategory = "screen"
if (safeUri.contains("/service/") || safeUri.contains("Services.xml")) {
    matchedCategory = "service"
} else if (safeUri.contains("/entity/") || safeUri.contains("Entities.xml")) {
    matchedCategory = "entity"
} else if (safeUri.contains("/screen/") || safeUri.endsWith(".xml")) {
    matchedCategory = "screen"
} else if (artifactType) {
    matchedCategory = artifactType.toLowerCase().replace("xml_", "")
}
context.detectedArtifactType = matchedCategory

// 3. MODE & ARTIFACT DIRECTIVE
String modeDirective = null
if (['discuss', 'orchestrate'].contains(normalizedMode)) {
    modeDirective = loadFirstResource([
        "component://agi-ide/mcp/instructions/artifacts/generic/${normalizedMode}.md",
        "component://agi-ai/mcp/instructions/artifacts/generic/${normalizedMode}.md"
    ])
} else {
    modeDirective = loadFirstResource([
        "component://agi-ide/mcp/instructions/artifacts/${matchedCategory}/${normalizedMode}.md",
        "component://agi-ai/mcp/instructions/artifacts/${matchedCategory}/${normalizedMode}.md",
        "component://agi-ide/mcp/instructions/artifacts/generic/${normalizedMode}.md",
        "component://agi-ai/mcp/instructions/artifacts/generic/${normalizedMode}.md"
    ])
}

if (modeDirective) {
    prompt.append("<!-- ============================================================= -->\n")
    prompt.append("<!-- MODE DIRECTIVE: ${normalizedMode.toUpperCase()} (${matchedCategory.toUpperCase()}) -->\n")
    prompt.append("<!-- ============================================================= -->\n")
    prompt.append(modeDirective.trim()).append("\n\n")
}

// 4. SITUATIONAL GROUNDING
if (targetComponent) {
    try {
        ResourceReference compRef = ec.resource.getLocationReference("component://${targetComponent}")
        if (compRef != null && compRef.getExists()) {
            prompt.append("### Active Workspace Target Component: ${targetComponent}\n")
            prompt.append("When suggesting paths or dependencies, anchor them to `component://${targetComponent}/...`.\n\n")
        }
    } catch (Exception ignore) {}
}

// 5. COMPLIANCE & BEHAVIORAL FACETS
Map facetMap = (facets ?: [:]) as Map
facetMap.each { fKey, fVal ->
    if (fVal == true || fVal == "true") {
        String cleanKey = fKey.toString().toLowerCase().replace("-", "").replace("_", "")
        String facetText = loadFirstResource([
            "component://agi-ide/mcp/instructions/facets/${cleanKey}.md",
            "component://agi-ai/mcp/instructions/facets/${cleanKey}.md"
        ])
        if (!facetText && cleanKey == "multitenant") {
            facetText = loadFirstResource([
                "component://agi-ide/mcp/instructions/facets/multi-tenant.md",
                "component://agi-ai/mcp/instructions/facets/multi-tenant.md"
            ])
        }
        if (facetText) {
            prompt.append("<!-- ============================================================= -->\n")
            prompt.append("<!-- COMPLIANCE FACET: ${fKey} -->\n")
            prompt.append("<!-- ============================================================= -->\n")
            prompt.append(facetText.trim()).append("\n\n")
        }
    }
}

context.systemInstruction = prompt.toString().trim()
